/** 🧳️ Retains only freshly preflighted current unready roots and closes each frame before canonical restaging. */
async function retainRepositoryDependencyUnreadyRootsV1(preflight:Awaited<ReturnType<typeof captureRepositoryDependencyUnreadyRootsV1>>,facts:Readonly<{sourceInputsSha256:string;sourceEndpointsSha256:string;recipeSha256:string;materializationSha256:string;fundingSha256:string}>,control:ResourceLeaseControl,checkpoint:()=>void,boundary:()=>Promise<void>){
 const stamp=(identity:ArtifactReadFileIdentityV1)=>JSON.stringify([identity.dev,identity.ino,identity.mode,identity.nlink,identity.size,identity.mtimeNs,identity.ctimeNs].map(String)),readyName=dependencyInstallSchema.$defs.ProducerUnreadyProtocol.const.readyName,retained:Array<Readonly<{scope:string;generation:string;directory:string;capsuleStamp:string;retained:Awaited<ReturnType<ArtifactRelativeDirectoryV1["retainPreservation"]>>["retained"]}>>=[],names=new Set(preflight.names);let parentStamp=preflight.parentStamp,transitionMayBeUnresolved=false,activeDirectory:string|null=null,intentSha256:string|null=null;
 const checkNames=async(directory:ArtifactRelativeDirectoryV1)=>{checkpoint();if(stamp(directory.stat())!==parentStamp||JSON.stringify(await directory.names())!==JSON.stringify([...names].sort((a,b)=>Buffer.compare(Buffer.from(a),Buffer.from(b)))))throw Error("Exact current unready parent CAS required");for(const row of preflight.selected){const entry=await directory.entry(row.name),moved=retained.some(value=>value.directory===row.directory);if((entry?stamp(entry):null)!==(moved?null:row.stamp))throw Error("Exact remaining unready selection required");}checkpoint();};
 try{
 for(const row of preflight.selected){await boundary();checkpoint();if(row.stamp===null)continue;activeDirectory=row.directory;let nextParent=parentStamp;const output=await withArtifactRelativeDirectoryV1(join(preflight.root,"j"),checkpoint,async directory=>{await checkNames(directory);const prior=await directory.entry(row.name);if(!prior||prior.kind!=="directory"||stamp(prior)!==row.stamp)throw Error("Exact selected unready root required");await directory.withDirectory(row.name,async child=>{if(stamp(child.stat())!==row.stamp||JSON.stringify(await child.names())!==JSON.stringify(row.names)||await child.entry(readyName)!==null)throw Error("Current unready root changed before retention");});
 const expected=await directory.capturePreservation(row.name);if(expected.kind!=="directory"||stamp(expected.identity)!==row.stamp)throw Error("Exact issued unready preservation required");const intent=javascriptDependencyUnreadyRetentionIntentV1({version:1,purpose:"retain-current-unready-dependency-generation",scope:row.scope,generation:row.generation,directory:row.directory,rootStamp:row.stamp,parentStamp,rosterSha256:row.rosterSha256,...facts,readyAbsent:true,directSourceReferences:0,inactivityProved:false});intentSha256=intent.sha256;transitionMayBeUnresolved=true;const output=await directory.retainPreservation(expected,intent.text),proof=output.retained,before=JSON.parse(row.stamp)as string[];
 if(output.name!==row.name||output.absent!==true||proof.kind!=="directory"||proof.intentSha256!==intent.sha256||String(proof.identity.dev)!==before[0]||String(proof.identity.ino)!==before[1]||await directory.entry(row.name)!==null)throw Error("Exact privately retained unready result required");const next=new Set(names);next.delete(row.name);if(next.has(proof.capsule))throw Error("Exclusive current unready capsule required");next.add(proof.capsule);nextParent=stamp(output.parent);if(stamp(directory.stat())!==nextParent||JSON.stringify(await directory.names())!==JSON.stringify([...next].sort((a,b)=>Buffer.compare(Buffer.from(a),Buffer.from(b)))))throw Error("Exact owned unready parent transition required");
 await directory.withDirectory(proof.capsule,async capsule=>{if(JSON.stringify(await capsule.names())!==JSON.stringify(["i","p","r"]))throw Error("Closed current unready capsule required");const payload=await capsule.entry("p");if(!payload||payload.kind!=="directory"||stamp(payload)!==stamp(proof.identity))throw Error("Exact retained unready payload required");await capsule.withDirectory("p",async child=>{if(JSON.stringify(await child.names())!==JSON.stringify(row.names)||await child.entry(readyName)!==null||stamp(child.stat())!==stamp(proof.identity))throw Error("Exact retained unready direct metadata required");});for(const[name,sha]of[["i",proof.intentSha256],["r",proof.receiptSha256]]as const)await capsule.withFile(name,async file=>{const identity=file.stat(),maximum=name==="i"?dependencyInstallSchema.$defs.ProducerUnreadyProtocol.const.maximumIntentBytes:dependencyInstallSchema.$defs.ProducerPreservationProtocol.const.maximumRetainedRecordBytes;if(identity.nlink!==1n||identity.size>BigInt(maximum))throw Error("Bounded owned unready record required");const before=stamp(identity),bytes=Buffer.alloc(maximum+1),count=file.read(bytes,0,bytes.length,0);if(count>maximum||file.read(bytes,0,1,count)!==0||createHash("sha256").update(bytes.subarray(0,count)).digest("hex")!==sha||stamp(file.stat())!==before)throw Error("Exact owned unready record changed");checkpoint();});});const capsule=await directory.entry(proof.capsule);if(!capsule||capsule.kind!=="directory")throw Error("Exact retained capsule descriptor required");checkpoint();return Object.freeze({retained:output.retained,capsuleStamp:stamp(capsule)});});
 parentStamp=nextParent;names.delete(row.name);names.add(output.retained.capsule);retained.push(Object.freeze({scope:row.scope,generation:row.generation,directory:row.directory,capsuleStamp:output.capsuleStamp,retained:output.retained}));transitionMayBeUnresolved=false;activeDirectory=null;intentSha256=null;await boundary();checkpoint();await control.publish({resource:"dependencies:unready-retained:"+retained.length,mode:"exclusive",elapsedMs:0});await control.yieldContinuation();checkpoint();
 }
 await boundary();await withArtifactRelativeDirectoryV1(join(preflight.root,"j"),checkpoint,async directory=>{await checkNames(directory);for(const row of preflight.selected)if(await directory.entry(row.name)!==null)throw Error("Fresh canonical generation absence required");});await boundary();checkpoint();return Object.freeze({version:1 as const,purpose:"retained-current-unready-dependency-generations"as const,retained:Object.freeze(retained),parentStamp,names:Object.freeze([...names]),inactivityProved:false as const,wholeAllocationRetired:false as const});
 }catch(error){try{console.error("[DATA] Dependency unready rebuild incomplete "+JSON.stringify({completedRetentions:retained.length,transitionMayBeUnresolved,activeDirectory,intentSha256,wholeAllocationRetired:false}));}catch(report){throw new AggregateError([error,report],"Unready rebuild and diagnostic delivery failed");}throw error;}
}
/** 🔨️ Derives current selected roots from actual plans, then freshly observes absence immediately before Core staging. */
async function prepareRepositoryDependencyUnreadyRebuildV1(root:string,captured:Awaited<ReturnType<typeof captureRepositoryDependencyProducerInputsV1>>,materialization:ReturnType<typeof readJavascriptDependencyProducerMaterializationV1>,fundingSha256:string,source:()=>Awaited<ReturnType<typeof readJavascriptDependencyPreservationSourceV1>>,control:ResourceLeaseControl,checkpoint:()=>void,boundary:()=>Promise<string>,read:<T>(body:(context:JavascriptDependencyReadContextV1)=>Promise<T>)=>Promise<T>,readyScopes:ReadonlySet<string>){
 const selected=captured.plans.filter(row=>!readyScopes.has(row.scope)).map(row=>Object.freeze({scope:row.scope,generation:row.plan.generation,directory:row.plan.directory})),relation=()=>readJavascriptDependencyUnreadySourceRelationsV1({version:1,purpose:"observe-current-unready-source-relations",root,selected:selected.map(({generation,directory})=>({generation,directory})),source:source()}),fence=async()=>{await boundary();checkpoint();relation();checkpoint();};await fence();const preflight=await read(context=>captureRepositoryDependencyUnreadyRootsV1(root,selected,control,()=>context.check(control)));await fence();const facts={sourceInputsSha256:captured.sourceSha256,sourceEndpointsSha256:source().sha256,recipeSha256:captured.recipeSha256,materializationSha256:createHash("sha256").update(JSON.stringify(materialization)).digest("hex"),fundingSha256},result=await read(context=>retainRepositoryDependencyUnreadyRootsV1(preflight,facts,control,()=>context.check(control),fence));await fence();await read(context=>withArtifactRelativeDirectoryV1(join(root,"j"),()=>context.check(control),async directory=>{for(const row of selected)if(await directory.entry(basename(row.directory))!==null)throw Error("Actual fresh canonical absence required immediately before staging");}));checkpoint();return result.retained;
}

